int nouveau_drm_debugfs_init ( struct drm_minor * minor ) { struct dentry * dentry ; int i ; for ( i = 0 ; i < ARRAY_SIZE ( nouveau_debugfs_files ) ; i ++ ) { dentry = debugfs_create_file ( nouveau_debugfs_files [ i ] . name , S_IRUGO | S_IWUSR , minor -> debugfs_root , minor -> dev , nouveau_debugfs_files [ i ] . fops ) ; } return drm_debugfs_create_files ( nouveau_debugfs_list , NOUVEAU_DEBUGFS_ENTRIES , minor -> debugfs_root , minor ) ; } 